import React from "react";
import "./Css.css";

const css = () => {
    const cssTopics = [
        {
            title: "CSS Syntax",
            code: "selector { property: value; }",
            example: `p {
  color: blue;
  font-size: 18px;
}`
        },
        {
            title: "Selectors",
            code: "element, .class, #id",
            example: `p { color: red; }
.box { padding: 20px; }
#header { background: black; }`
        },
        {
            title: "Colors",
            code: "color, background-color",
            example: `h1 {
  color: #2563eb;
  background-color: #f1f5f9;
}`
        },
        {
            title: "Text",
            code: "font-size, font-family, font-weight, text-align",
            example: `p {
  font-size: 18px;
  font-family: Arial;
  font-weight: bold;
  text-align: center;
}`
        },
        {
            title: "Margin",
            code: "margin",
            example: `.box {
  margin: 20px;
  margin-top: 10px;
  margin-right: 15px;
  margin-bottom: 20px;
  margin-left: 25px;
}`
        },
        {
            title: "Padding",
            code: "padding",
            example: `.box {
  padding: 20px;
  padding-top: 10px;
  padding-right: 15px;
  padding-bottom: 20px;
  padding-left: 25px;
}`
        },
        {
            title: "Border",
            code: "border, border-radius",
            example: `.box {
  border: 2px solid black;
  border-radius: 10px;
}`
        },
        {
            title: "Width & Height",
            code: "width, height, max-width, min-height",
            example: `.box {
  width: 300px;
  height: 200px;
  max-width: 100%;
}`
        },
        {
            title: "Display",
            code: "block, inline, inline-block, none",
            example: `.box {
  display: block;
}

.menu {
  display: inline-block;
}`
        },
        {
            title: "Flexbox",
            code: "display: flex",
            example: `.container {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 20px;
}`
        },
        {
            title: "Grid",
            code: "display: grid",
            example: `.container {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}`
        },
        {
            title: "Position",
            code: "static, relative, absolute, fixed, sticky",
            example: `.box {
  position: absolute;
  top: 20px;
  left: 30px;
}`
        },
        {
            title: "Background",
            code: "background, background-image",
            example: `.hero {
  background: linear-gradient(135deg, #2563eb, #7c3aed);
}`
        },
        {
            title: "Shadow",
            code: "box-shadow, text-shadow",
            example: `.card {
  box-shadow: 0 10px 30px rgba(0,0,0,0.15);
}`
        },
        {
            title: "Transition",
            code: "transition",
            example: `.button {
  transition: 0.3s;
}

.button:hover {
  transform: scale(1.05);
}`
        },
        {
            title: "Transform",
            code: "scale, rotate, translate, skew",
            example: `.box {
  transform: translateY(-10px);
  transform: rotate(5deg);
}`
        },
        {
            title: "Hover",
            code: ":hover",
            example: `.button:hover {
  background-color: black;
  color: white;
}`
        },
        {
            title: "Pseudo Elements",
            code: "::before, ::after",
            example: `.title::before {
  content: "★";
  margin-right: 5px;
}`
        },
        {
            title: "CSS Variables",
            code: "--variable, var()",
            example: `:root {
  --primary: #2563eb;
}

button {
  background: var(--primary);
}`
        },
        {
            title: "Media Query",
            code: "@media",
            example: `@media (max-width: 768px) {
  .container {
    grid-template-columns: 1fr;
  }
}`
        }
    ];

    return (
        <>
            <div className="css-cheatsheet">

                <header className="css-header">
                    <span className="css-badge">CSS</span>

                    <h1>
                        CSS Cheat Sheet
                    </h1>

                    <p>
                        Quick reference for CSS properties, selectors,
                        layouts, effects and responsive design.
                    </p>
                </header>

                <div className="css-stats">
                    <div className="css-stat">
                        <strong>{cssTopics.length}</strong>
                        <span>Topics</span>
                    </div>

                    <div className="css-stat">
                        <strong>Basics</strong>
                        <span>To Advanced</span>
                    </div>

                    <div className="css-stat">
                        <strong>Responsive</strong>
                        <span>Design</span>
                    </div>
                </div>

                <section className="css-grid">
                    {cssTopics.map((topic, index) => (
                        <div className="css-card" key={index}>

                            <div className="css-card-top">
                                <span className="css-number">
                                    {String(index + 1).padStart(2, "0")}
                                </span>

                                <h2>{topic.title}</h2>
                            </div>

                            <div className="css-syntax">
                                {topic.code}
                            </div>

                            <pre className="css-code">
                                <code>{topic.example}</code>
                            </pre>

                        </div>
                    ))}
                </section>

                <div className="css-footer">
                    <span>CSS Cheat Sheet</span>
                    <span>•</span>
                    <span>Learn CSS Step by Step</span>
                </div>

            </div>
        </>
    )
}

export default css
